{
  "judgments": [
    {
      "issue_id": "region.4f8c45ab9e1452b9f7a9d8fd",
      "printed_text": "54/F, One Island East, 18 Westlands Road, Quarry Bay, Hong Kong\n香港鰂魚涌華蘭路 18 號港島東中心 54 樓\n+852 2231 1222    www.sfc.hk\nPage 5 of 6",
      "classification": "reading_order_change",
      "explanation": "This text is printed in the footer. Together with the matching insertion in region.1eaa5de7addd6a5f1b972dfc, the deletion represents relocation from the beginning to the end of the extracted text, not a net omission. Preserve the footer text and its separation from the advertisement.",
      "uncertainty": "The Chinese footer is small and pale; its wording is readable, but exact intercharacter spacing is not reliably distinguishable."
    },
    {
      "issue_id": "region.5f3e2ac530b9ddb116e57f80",
      "printed_text": "the 30-day annualised return",
      "classification": "typographic_only",
      "explanation": "Warning 6 prints the compound as “30-day”. Splitting “30-” and “day” into separate tokens does not change the number, period or wording when joined correctly.",
      "uncertainty": "The supplied locations include several occurrences; the token sequence identifies the annualised-return phrase in warning 6."
    },
    {
      "issue_id": "region.dd6e20e16e9dbe718030f0bb",
      "printed_text": "based on 1-day period",
      "classification": "typographic_only",
      "explanation": "Warning 6 prints “1-day” with a hyphen. The difference between tokens “1”, “-day” and the single token “1-day” is segmentation only.",
      "uncertainty": "The supplied locations include unrelated and repeated numeric matches; the changed token sequence identifies the period description in warning 6."
    },
    {
      "issue_id": "region.5532251c138c931564f0a104",
      "printed_text": "7-day period",
      "classification": "typographic_only",
      "explanation": "Warning 6 prints “7-day”. Joining the tokens “7” and “-day” preserves the printed number and unit.",
      "uncertainty": "Several occurrences are included in the location list; the changed token sequence identifies the period description in warning 6."
    },
    {
      "issue_id": "region.fb75ebf127ab185001b2e42b",
      "printed_text": "30-day period",
      "classification": "typographic_only",
      "explanation": "Warning 6 prints “30-day period”. The split between “30-” and “day” is a tokenization difference, with no omitted number, unit or word.",
      "uncertainty": "Several occurrences are included in the location list; the changed token sequence identifies the period description in warning 6."
    },
    {
      "issue_id": "region.0de763e3a0123d4f35710fd8",
      "printed_text": "do not represent an actual one-\nyear return.",
      "classification": "text_changed",
      "explanation": "The printed line ends with “one-”, and the next line begins “year return.” A faithful continuous transcription is “do not represent an actual one-year return.” The replacement “oneyear” drops the visible hyphen and fuses the words. This is a transcription defect even though the intended meaning remains recoverable.",
      "uncertainty": "The line break is clear. The image does not independently establish whether the hyphen was encoded as a discretionary character; it is nevertheless visible and should not be normalized to “oneyear”."
    },
    {
      "issue_id": "region.0d3a2c50ba6f1541e2174a76",
      "printed_text": "Most recent 1-year return is calculated by annualising the change of NAV,",
      "classification": "typographic_only",
      "explanation": "The computation-basis bullet prints “1-year”. The difference between “1”, “-year” and “1-year” is token segmentation only. The return heading also reads “Most recent 1-year return*: XX%”.",
      "uncertainty": "The locations include both the heading and the computation bullet; the changed token sequence identifies the bullet."
    },
    {
      "issue_id": "region.8c7f1397703434a553b862e3",
      "printed_text": "#For the most up-to-date daily figure, please refer to [www.xxx.com].",
      "classification": "typographic_only",
      "explanation": "The initial “#” is a superscript footnote marker preceding “For”. It corresponds to the superscript “#” following “XX%” in the 1-day annualised-return display. Splitting “#For” into “#” and “For” preserves the text, provided the marker and its footnote association are retained.",
      "uncertainty": "Plain token strings do not preserve superscript positioning; the image establishes that positioning."
    },
    {
      "issue_id": "region.44cc4c16ca1b39bf72c0b429",
      "printed_text": "Returns [(which are calculated based on the change of NAV, [with/without] dividend reinvested)] of the immediately preceding 5 years:",
      "classification": "typographic_only",
      "explanation": "The notes print the closing sequence “reinvested)]”. Both tokenizations preserve the closing parenthesis followed by the closing square bracket. The bracketed “[with/without]” alternative is also printed and must remain in the transcription.",
      "uncertainty": "None material to the identified punctuation sequence."
    },
    {
      "issue_id": "region.1eaa5de7addd6a5f1b972dfc",
      "printed_text": "54/F, One Island East, 18 Westlands Road, Quarry Bay, Hong Kong\n香港鰂魚涌華蘭路 18 號港島東中心 54 樓\n+852 2231 1222    www.sfc.hk\nPage 5 of 6",
      "classification": "reading_order_change",
      "explanation": "The inserted tokens reproduce the printed footer. Paired with region.4f8c45ab9e1452b9f7a9d8fd, this is relocation to the end of the extraction, consistent with the footer's visual position, rather than newly added source content. “Page 5 of 6” is the printed page label.",
      "uncertainty": "Exact spacing within the small Chinese footer and between the telephone number and website is not reliably recoverable from the rendering."
    },
    {
      "issue_id": "region.8895bd83273e671bc82bbdcb",
      "printed_text": "54/F, One Island East, 18 Westlands Road, Quarry Bay, Hong Kong\n香港鰂魚涌華蘭路 18 號港島東中心 54 樓\n+852 2231 1222    www.sfc.hk\nPage 5 of 6",
      "classification": "text_omitted_or_relocated",
      "explanation": "The deleted text is visibly present in the footer, so its removal cannot be dismissed as typography. This issue duplicates the footer deletion reported above. It is a reading-order change if the same comparison retains the footer at the end; otherwise it omits printed contact information and the page label.",
      "uncertainty": "The supplied records do not establish whether the matching footer insertion belongs to this duplicate deletion's comparison."
    },
    {
      "issue_id": "region.11e421c02405e36ec0044194",
      "printed_text": "the 30-day annualised return",
      "classification": "typographic_only",
      "explanation": "This repeats the token difference in region.5f3e2ac530b9ddb116e57f80. The page prints “30-day”; joining “30-” and “day” preserves the printed wording and period.",
      "uncertainty": "The location list contains multiple occurrences; the token sequence identifies the annualised-return phrase in warning 6."
    }
  ],
  "remaining_questions": [
    "Does region.8895bd83273e671bc82bbdcb belong to a comparison that also inserts the footer at the end? That pairing is needed to distinguish relocation from omission for this duplicate record."
  ]
}
